package com.harish.student_management.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="certificate_templates") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class CertificateTemplate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,length=40) String certificateType; @Column(nullable=false,columnDefinition="TEXT") String template; @Column(name="created_at",updatable=false) LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();} }
